-- 0595_seed_curated_donation_links | FR-DONATE-006/007, D9
-- Seeds a curated starter directory of Israeli (or large, well-known international) bodies into
-- the community links of every category. Each URL was fetched and its page content checked on
-- 2026-11-03; each description restates only what the linked page itself says, so the URL is
-- the source of every fact. Pages that could not be verified (blocked, empty, wrong site) were left out.
--
-- Ownership: rows are attributed to the first super admin (donation_links.submitted_by is NOT NULL
-- and references auth.users). If no super admin exists yet (fresh database) the migration is a no-op.
-- The review guard (0546) forces every insert to 'pending', so the seeded rows are then approved
-- by the curator; migrations run as the table owner, which the guard allows.
-- Idempotent: a (category, url) pair that already exists is skipped.

begin;

do $$
declare
  v_curator uuid;
begin
  select u.user_id into v_curator
    from public.users u
   where public.has_admin_role(u.user_id, 'super_admin')
   order by u.user_id
   limit 1;

  if v_curator is null then
    raise notice '0595: no super admin found, curated donation links not seeded';
    return;
  end if;

  create temp table curated_links (category_slug text, url text, display_name text, description text) on commit drop;

  insert into curated_links (category_slug, url, display_name, description) values
  -- time
  ('time', 'https://www.we-me.app/', 'לב אחד – פלטפורמת ההתנדבות הלאומית', 'פלטפורמה לאיתור משימות התנדבות בזמן אמת בפריסה ארצית ולניהול ההתנדבויות במקום אחד, עם עשרות אלפי מתנדבים.'),
  ('time', 'https://ivolunteer.org.il/', 'המועצה הישראלית להתנדבות', 'סטארט-אפ חברתי לפיתוח תשתיות, מודלים, למידה וכלים לקידום התנדבות והשתתפות חברתית בישראל.'),
  ('time', 'https://www.ruachtova.org.il/', 'רוח טובה – התנדבות בהתאמה אישית', 'מחברת בין מתנדבים לעמותות וגופים ללא מטרות רווח הזקוקים לכוח התנדבות, כך שאפשר למצוא התנדבות בזמן שלכם ובכל מקום בארץ.'),
  ('time', 'https://www.yedidim.org.il/', 'עמותת ידידים – התנדבות', 'ארגון לילדים, נוער וצעירים במצבי סיכון ומצוקה; מפעיל מאות סטודנטים ומתנדבים בתוכניות חינוך ורווחה ברחבי הארץ ומציע להצטרף כמתנדבים.'),
  ('time', 'https://www.perach.org.il/', 'פר"ח – חונכות בקהילה', 'תוכנית חונכות שבה סטודנטים מתנדבים כחונכים לילדים וצעירים, עם עשרות אלפי חונכים וחניכים מדי שנה ברחבי הארץ.'),
  ('time', 'https://zaka.org.il/', 'זק"א – איתור, חילוץ והצלה', 'ארגון מתנדבים לאיתור, חילוץ והצלה ולכיבוד המת, הפועל בכל שעות היממה; באתר אפשר להתעניין בהתנדבות.'),
  ('time', 'https://www.bsil.org.il/', 'אחים ואחיות לישראל – חמ"ל אזרחי', 'חמ"ל אזרחי המגיב לצרכים דחופים של חיילים, משפחות מפונות ואזרחים, בסיוע רשת מתנדבים; באתר קישור להצטרפות להתנדבות.'),
  ('time', 'https://www.matnasim.org.il/', 'החברה למתנ"סים', 'הזרוע החברתית של המדינה: כ-200 מרכזים קהילתיים ו-1,000 שלוחות, בהם פועלים כ-30,000 מתנדבים ומתנדבות.'),
  ('time', 'https://yadsarah.org/', 'יד שרה', 'ארגון מתנדבים מוביל בישראל המשאיל ציוד רפואי ושיקומי; המתנדבים מסייעים למצוא את הציוד המתאים.'),
  -- money
  ('money', 'https://www.ogen.org/', 'עוגן – קרן הלוואות ומנטורינג חברתית', 'קרן ללא כוונת רווח המעניקה הלוואות בתנאים הוגנים וליווי אישי לפרטים, משפחות, עסקים ועמותות.'),
  ('money', 'https://www.paamonim.org/he/', 'פעמונים – ייעוץ כלכלי בחינם', 'עמותה המספקת ייעוץ כלכלי וליווי פיננסי ללא עלות למשפחות וליחידים בכל הגילאים.'),
  ('money', 'https://www.latet.org.il/', 'לתת – סיוע הומניטרי ישראלי', 'ארגון גג לצמצום העוני בישראל: חבילות מזון ומוצרי היגיינה למשפחות נזקקות; באתר אפשר לתרום או להתנדב.'),
